import{_ as a,a0 as o,w as p,s as d,I as n,x as i,a1 as e,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 LVM 上安裝 Linux Mint | LCTT x X-CMD","titleTemplate":false,"description":"在 LVM 上安裝 Linux Mint | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 LVM 上安裝 Linux Mint | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 LVM 上安裝 Linux Mint | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210813 Install Linux with LVM","title":"在 LVM 上安裝 Linux Mint","tag":"202108","desc":""},"relativePath":"202108/20210813 Install Linux with LVM.md","filePath":"[post].md"}'),u={name:"202108/20210813 Install Linux with LVM.md"};function g(L,t,m,x,f,M){const s=o("Link");return p(),d("div",null,[t[28]||(t[28]=n("h1",{id:"在-lvm-上安裝-linux-mint",tabindex:"-1"},[i("在 LVM 上安裝 Linux Mint "),n("a",{class:"header-anchor",href:"#在-lvm-上安裝-linux-mint","aria-label":"Permalink to “在 LVM 上安裝 Linux Mint”"},"​")],-1)),t[29]||(t[29]=n("blockquote",null,[n("p",null,"一個關於讓 Linux Mint 20.2 與邏輯卷管理器（LVM）一起工作的教程。")],-1)),t[30]||(t[30]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/21/104418yg111cba52caalc5.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=i("幾周前，",-1)),e(s,{href:"https://linuxmint.com/"},{default:l(()=>[...t[0]||(t[0]=[i("Linux Mint",-1)])]),_:1}),t[2]||(t[2]=i(" 的人員發佈了他們的開源操作系統的 20.2 版本。Live ISO 中內置的安裝程序非常好，只需要點擊幾下就可以安裝操作系統。如果你想定製你的分區，你甚至有一個內置的分區軟件。",-1))]),n("p",null,[t[5]||(t[5]=i("安裝程序重點關注在簡單的安裝上：定義你的分區並安裝到這些分區。對於那些想要更靈活的設置的人來説，",-1)),n("ruby",null,[e(s,{href:"https://en.wikipedia.org/wiki/Logical_Volume_Manager_(Linux)"},{default:l(()=>[...t[3]||(t[3]=[i("邏輯卷管理器",-1)])]),_:1}),t[4]||(t[4]=n("rt",null,"logical volume manager",-1))]),t[6]||(t[6]=i("（LVM）是個不錯的選擇，你可以通過設置卷組（VG）並在其中定義你的邏輯卷（LV）。",-1))]),n("p",null,[t[8]||(t[8]=i("LVM 是一個硬盤管理系統，允許你在多個物理驅動器上創建存儲空間。換句話説，你可以把幾個小驅動器“拴”在一起，這樣你的操作系統就會把它們當作一個驅動器。除此之外，它還有實時調整大小、文件系統快照和更多的優點。這篇文章並不是關於 LVM 的教程（網上已經有很多 ",-1)),e(s,{href:"https://opensource.com/business/16/9/linux-users-guide-lvm"},{default:l(()=>[...t[7]||(t[7]=[i("這方面不錯的信息",-1)])]),_:1}),t[9]||(t[9]=i("了）。相反，我的目標是貼合這篇文章的主題，只關注讓 Linux Mint 20.2 與 LVM 一起工作。",-1))]),t[31]||(t[31]=n("p",null,"作為一個桌面操作系統，其安裝程序致力於簡單化，在 LVM 上安裝 Linux Mint 20.2 會略微複雜一些，但不會太複雜。如果你在安裝程序中選擇了 LVM，你會得到一個由 Linux Mint 開發者定義的設置，而且你在安裝時無法控制各個卷。",-1)),t[32]||(t[32]=n("p",null,"然而，有一個解決方案：在臨場 ISO 中，該方案只需要在終端中使用幾個命令來設置 LVM，然後你可以繼續使用常規安裝程序來完成工作。",-1)),n("p",null,[t[11]||(t[11]=i("我安裝了 Linux Mint 20.2 和 ",-1)),e(s,{href:"https://opensource.com/article/19/12/xfce-linux-desktop"},{default:l(()=>[...t[10]||(t[10]=[i("XFCE 桌面",-1)])]),_:1}),t[12]||(t[12]=i("，但其他 Linux Mint 桌面的過程也類似。",-1))]),t[33]||(t[33]=r(`<h3 id="分區驅動器" tabindex="-1">分區驅動器 <a class="header-anchor" href="#分區驅動器" aria-label="Permalink to “分區驅動器”">​</a></h3><p>在 Linux Mint 臨場 ISO 中，你可以通過終端和 GUI 工具訪問 Linux 命令列工具。如果你需要做任何分區工作，你可以使用命令列 <code>fdisk</code> 或 <code>parted</code> 命令，或者 GUI 應用 <code>gparted</code>。我想讓這些操作簡單到任何人都能遵循，所以我會在可能的情況下使用 GUI 工具，在必要時使用命令列工具。</p><p>首先，為安裝創建幾個分區。</p><p>使用 <code>gparted</code>（從菜單中啓動），完成以下工作：</p><p>首先，創建一個 512MB 的分區，類型為 FAT32（這是用來確保系統可啓動）。512MB 對大多數人來説是富餘的，你可以用 256MB 甚至更少，但在今天的大容量磁盤中，即使分配 512MB 也不是什麼大問題。</p><p><img src="https://opensource.com/sites/default/files/boot-part.png" alt="Creating a boot partition" title="Creating a boot partition"></p><p>接下來，在磁盤的其餘部分創建一個 <code>lvm2 pv</code> 類型（LVM 2 物理卷）的分區（這是你的 LVM 的位置）。</p><p><img src="https://opensource.com/sites/default/files/part-layout.png" alt="Partition layout" title="Partition layout"></p><p>現在打開一個終端窗口，並將你的權限提升到 root：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -s</span></span>
<span class="line"><span># whoami</span></span>
<span class="line"><span>root</span></span></code></pre></div><p>接下來，你必須找到你之前創建的 LVM 成員（那個大分區）。使用下列命令之一：<code>lsblk -f</code> 或 <code>pvs</code> 或 <code>pvscan</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pvs</span></span>
<span class="line"><span>PV      VG Fmt  [...]</span></span>
<span class="line"><span>/dev/sda2    lvm2 [...]</span></span></code></pre></div><p>在我的例子中，該分區位於 <code>/dev/sda2</code>，但你應該用你的輸出中得到的內容來替換它。</p><p>現在你知道了你的分區有哪些設備，你可以在那裏創建一個 LVM 卷組（VG）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vgcreate vg /dev/sda2</span></span></code></pre></div><p>你可以使用 <code>vgs</code> 或 <code>vgscan</code> 看到你創建的卷組的細節。</p><p>創建你想在安裝時使用的邏輯卷（LV）。為了簡單，我分別創建了 <code>root</code> 根分區（<code>/</code>）和 <code>swap</code> 交換分區，但是你可以根據需要創建更多的分區（例如，為 <code>/home</code> 創建一個單獨的分區）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lvcreate -L 80G -n root vg</span></span>
<span class="line"><span># lvcreate -L 16G -n swap vg</span></span></code></pre></div><p>我的例子中的分區大小是任意的，是基於我可用的空間。使用對你的硬盤有意義的分區大小。</p><p>你可以用 <code>lvs</code> 或 <code>lvdisplay</code> 查看邏輯卷。</p><p>終端操作到這就結束了。</p><h3 id="安裝-linux" tabindex="-1">安裝 Linux <a class="header-anchor" href="#安裝-linux" aria-label="Permalink to “安裝 Linux”">​</a></h3><p>現在從桌面上的圖標啓動安裝程序：</p><ul><li>進入 “Installation type”，選擇 “Something else”。</li><li>編輯 512Mb 的分區並將其改為 <code>EFI</code>。</li><li>編輯根邏輯卷，將其改為 <code>ext4</code>（或一個你選擇的文件系統）。選擇將其掛載為根目錄（<code>/</code>），並選擇將其格式化。</li><li>編輯 <code>swap</code> 分區並將其設置為交換分區。</li><li>繼續正常的安裝過程。Linux Mint 安裝程序會將文件放在正確的位置併為你創建掛載點。</li></ul><p>完成了。在你的 Linux Mint 安裝中享受 LVM 的強大。</p><p>如果你需要調整分區大小或在系統上做任何高級工作，你會感謝選擇 LVM。</p><hr>`,27)),n("p",null,[t[14]||(t[14]=i("via: ",-1)),e(s,{href:"https://opensource.com/article/21/8/install-linux-mint-lvm"},{default:l(()=>[...t[13]||(t[13]=[i("https://opensource.com/article/21/8/install-linux-mint-lvm",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=i("作者：",-1)),e(s,{href:"https://opensource.com/users/flyingrhino"},{default:l(()=>[...t[15]||(t[15]=[i("Kenneth Aaron",-1)])]),_:1}),t[20]||(t[20]=i(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[16]||(t[16]=[i("lujun9972",-1)])]),_:1}),t[21]||(t[21]=i(" 譯者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[17]||(t[17]=[i("geekpi",-1)])]),_:1}),t[22]||(t[22]=i(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[18]||(t[18]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[23]||(t[23]=[i("LCTT",-1)])]),_:1}),t[26]||(t[26]=i(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[24]||(t[24]=[i("Linux中國",-1)])]),_:1}),t[27]||(t[27]=i(" 榮譽推出",-1))])])}const v=a(u,[["render",g]]);export{h as __pageData,v as default};
